changeSet.sql:
            CREATE TABLE "public"."dsapi_config"
            (
                "id"             text COLLATE "pg_catalog"."default" NOT NULL,
                "name"           text COLLATE "pg_catalog"."default",
                "note"           text COLLATE "pg_catalog"."default",
                "path"           text COLLATE "pg_catalog"."default" NOT NULL,
                "params"         text COLLATE "pg_catalog"."default",
                "json_param"     text COLLATE "pg_catalog"."default",
                "status"         int4,
                "access"         int4,
                "group_id"       text COLLATE "pg_catalog"."default",
                "content_type"   text COLLATE "pg_catalog"."default",
                "task"           text COLLATE "pg_catalog"."default",
                "create_user_id" text COLLATE "pg_catalog"."default",
                "create_time"    text COLLATE "pg_catalog"."default",
                "update_time"    text COLLATE "pg_catalog"."default",
                "del_is"         varchar(255) COLLATE "pg_catalog"."default",
                "time_create"    timestamp(6),
                "time_update"    timestamp(6),
                "name_create"    text COLLATE "pg_catalog"."default",
                "name_update"    text COLLATE "pg_catalog"."default",
                CONSTRAINT "api_config_pkey" PRIMARY KEY ("id")
            )
            ;

            ALTER TABLE "public"."dsapi_config"
                OWNER TO "postgres";

            COMMENT
            ON COLUMN "public"."dsapi_config"."id" IS '主键';

COMMENT
            ON COLUMN "public"."dsapi_config"."name" IS '名称';

COMMENT
            ON COLUMN "public"."dsapi_config"."note" IS '备注';

COMMENT
            ON COLUMN "public"."dsapi_config"."path" IS '接口定义的路径';

COMMENT
            ON COLUMN "public"."dsapi_config"."params" IS '参数信息';

COMMENT
            ON COLUMN "public"."dsapi_config"."json_param" IS '入参信息';

COMMENT
            ON COLUMN "public"."dsapi_config"."status" IS '状态，停用与否';

COMMENT
            ON COLUMN "public"."dsapi_config"."access" IS 'api类型';

COMMENT
            ON COLUMN "public"."dsapi_config"."group_id" IS '分组Id';

COMMENT
            ON COLUMN "public"."dsapi_config"."content_type" IS '请求头';

COMMENT
            ON COLUMN "public"."dsapi_config"."task" IS '该任务信息';

COMMENT
            ON COLUMN "public"."dsapi_config"."create_user_id" IS '创建人Id';

COMMENT
            ON COLUMN "public"."dsapi_config"."create_time" IS '创建时间';

COMMENT
            ON COLUMN "public"."dsapi_config"."update_time" IS '更新时间';

COMMENT
            ON COLUMN "public"."dsapi_config"."del_is" IS '是否删除标识';

COMMENT
            ON COLUMN "public"."dsapi_config"."time_create" IS '创建时间';

COMMENT
            ON COLUMN "public"."dsapi_config"."time_update" IS '更新时间';

COMMENT
            ON COLUMN "public"."dsapi_config"."name_create" IS '创建人名称';

COMMENT
            ON COLUMN "public"."dsapi_config"."name_update" IS '更新人名称';

COMMENT
            ON TABLE "public"."dsapi_config" IS 'api配置信息';

            CREATE TABLE "public"."dsapi_datasource"
            (
                "id"             text COLLATE "pg_catalog"."default" NOT NULL,
                "name"           text COLLATE "pg_catalog"."default",
                "note"           text COLLATE "pg_catalog"."default",
                "type"           text COLLATE "pg_catalog"."default",
                "url"            text COLLATE "pg_catalog"."default",
                "username"       text COLLATE "pg_catalog"."default",
                "password"       text COLLATE "pg_catalog"."default",
                "driver"         text COLLATE "pg_catalog"."default",
                "table_sql"      text COLLATE "pg_catalog"."default",
                "create_user_id" int4,
                "create_time"    text COLLATE "pg_catalog"."default",
                "update_time"    text COLLATE "pg_catalog"."default",
                "del_is"         varchar(255) COLLATE "pg_catalog"."default",
                "time_create"    timestamp(6),
                "time_update"    timestamp(6),
                "name_create"    text COLLATE "pg_catalog"."default",
                "name_update"    text COLLATE "pg_catalog"."default",
                CONSTRAINT "datasource_pkey" PRIMARY KEY ("id")
            )
            ;

            ALTER TABLE "public"."dsapi_datasource"
                OWNER TO "postgres";

            COMMENT
            ON COLUMN "public"."dsapi_datasource"."id" IS '名称';

COMMENT
            ON COLUMN "public"."dsapi_datasource"."name" IS '名称';

COMMENT
            ON COLUMN "public"."dsapi_datasource"."note" IS '备注信息';

COMMENT
            ON COLUMN "public"."dsapi_datasource"."type" IS '类型';

COMMENT
            ON COLUMN "public"."dsapi_datasource"."url" IS 'jdbcUrl';

COMMENT
            ON COLUMN "public"."dsapi_datasource"."username" IS '用户名';

COMMENT
            ON COLUMN "public"."dsapi_datasource"."password" IS '密码';

COMMENT
            ON COLUMN "public"."dsapi_datasource"."driver" IS '驱动名称';

COMMENT
            ON COLUMN "public"."dsapi_datasource"."table_sql" IS '创建或编辑API的时候，选择数据源，会执行此sql来获取该数据源下的所有表名称';

COMMENT
            ON COLUMN "public"."dsapi_datasource"."create_user_id" IS '创建人';

COMMENT
            ON COLUMN "public"."dsapi_datasource"."create_time" IS '创建时间';

COMMENT
            ON COLUMN "public"."dsapi_datasource"."update_time" IS '更新时间';

COMMENT
            ON COLUMN "public"."dsapi_datasource"."del_is" IS '是否删除标识';

COMMENT
            ON COLUMN "public"."dsapi_datasource"."time_create" IS '创建时间';

COMMENT
            ON COLUMN "public"."dsapi_datasource"."time_update" IS '更新时间';

COMMENT
            ON COLUMN "public"."dsapi_datasource"."name_create" IS '创建人名称';

COMMENT
            ON COLUMN "public"."dsapi_datasource"."name_update" IS '更新人名称';

COMMENT
            ON TABLE "public"."dsapi_datasource" IS '数据源信息';

            CREATE TABLE "public"."dsapi_group"
            (
                "id"             text COLLATE "pg_catalog"."default" NOT NULL,
                "name"           text COLLATE "pg_catalog"."default" NOT NULL,
                "create_user_id" int4,
                "create_time"    text COLLATE "pg_catalog"."default",
                "update_time"    text COLLATE "pg_catalog"."default",
                "time_create"    timestamp(6),
                "time_update"    timestamp(6),
                "name_create"    text COLLATE "pg_catalog"."default",
                "name_update"    text COLLATE "pg_catalog"."default",
                CONSTRAINT "api_group_pkey" PRIMARY KEY ("id")
            )
            ;

            ALTER TABLE "public"."dsapi_group"
                OWNER TO "postgres";

            COMMENT
            ON COLUMN "public"."dsapi_group"."id" IS '主键';

COMMENT
            ON COLUMN "public"."dsapi_group"."name" IS '分组名称';

COMMENT
            ON COLUMN "public"."dsapi_group"."create_user_id" IS '创建人Id';

COMMENT
            ON COLUMN "public"."dsapi_group"."create_time" IS '创建时间';

COMMENT
            ON COLUMN "public"."dsapi_group"."update_time" IS '更新时间';

COMMENT
            ON COLUMN "public"."dsapi_group"."time_create" IS '创建时间';

COMMENT
            ON COLUMN "public"."dsapi_group"."time_update" IS '更新时间';

COMMENT
            ON COLUMN "public"."dsapi_group"."name_create" IS '创建人名称';

COMMENT
            ON COLUMN "public"."dsapi_group"."name_update" IS '更新人名称';

COMMENT
            ON TABLE "public"."dsapi_group" IS 'api分组信息';
